package pool

import "sync"

// Task is a unit of work with an integer result.
type Task struct {
	ID  int
	Fn  func() int
}

// Result holds the output of a completed task.
type Result struct {
	ID    int
	Value int
}

// Pool is a fixed-size goroutine worker pool.
type Pool struct {
	workers int
	tasks   chan Task
	results chan Result
	wg      sync.WaitGroup
	once    sync.Once
}

// New creates a pool with n workers.
func New(n int) *Pool {
	return &Pool{
		workers: n,
		tasks:   make(chan Task, 64),
		results: make(chan Result, 64),
	}
}

// Start launches the worker goroutines.
