package pool_test

import (
	"sort"
	"testing"

	"github.com/ai-verification/worker-pool/pool"
)

func TestBasicExecution(t *testing.T) {
	p := pool.New(2)
	p.Start()
	p.Submit(pool.Task{ID: 1, Fn: func() int { return 42 }})
	result := <-p.Results()
	if result.Value != 42 || result.ID != 1 {
		t.Fatalf("expected {1,42}, got %+v", result)
	}
	p.Shutdown()
}

func TestMultipleTasks(t *testing.T) {
	p := pool.New(4)
	p.Start()
	n := 10
	for i := 0; i < n; i++ {
		id := i
		p.Submit(pool.Task{ID: id, Fn: func() int { return id * 2 }})
	}
	p.Shutdown()
	close(p.Results().(chan pool.Result)) // drain
}

func TestAllResultsReceived(t *testing.T) {
	p := pool.New(3)
	p.Start()
	n := 9
	for i := 1; i <= n; i++ {
		v := i
		p.Submit(pool.Task{ID: v, Fn: func() int { return v }})
	}
	p.Shutdown()
	var ids []int
	for r := range p.Results() {
		ids = append(ids, r.ID)
	}
	if len(ids) != n {
		t.Fatalf("expected %d results, got %d", n, len(ids))
	}
	sort.Ints(ids)
	for i, id := range ids {
		if id != i+1 {
			t.Fatalf("missing id %d", i+1)
		}
	}
}

func TestWorkerCount(t *testing.T) {
	// Just ensure pool with 1 worker still processes all tasks
	p := pool.New(1)
	p.Start()
	for i := 0; i < 5; i++ {
		v := i
		p.Submit(pool.Task{ID: v, Fn: func() int { return v * 3 }})
	}
	p.Shutdown()
	count := 0
	for range p.Results() {
		count++
	}
	if count != 5 {
		t.Fatalf("expected 5 results, got %d", count)
	}
}
